  `status_id` INTEGER,
  `address_status` TEXT,
  PRIMARY KEY (`status_id`)
);

CREATE TABLE `author` (
  `author_id` INTEGER,
  `author_name` TEXT,
  PRIMARY KEY (`author_id`)
);

CREATE TABLE `book_language` (
  `language_id` INTEGER,
  `language_code` TEXT,
  `language_name` TEXT,
  PRIMARY KEY (`language_id`)
);

CREATE TABLE `country` (
  `country_id` INTEGER,
  `country_name` TEXT,
  PRIMARY KEY (`country_id`)
);

CREATE TABLE `address` (
  `address_id` INTEGER,
  `street_number` TEXT,
  `street_name` TEXT,
  `city` TEXT,
  `country_id` INTEGER REFERENCES `country`(`country_id`),
  PRIMARY KEY (`address_id`)
);

CREATE TABLE `customer` (
  `customer_id` INTEGER,
  `first_name` TEXT,
  `last_name` TEXT,
  `email` TEXT,
  PRIMARY KEY (`customer_id`)
);

CREATE TABLE `customer_address` (
  `customer_id` INTEGER REFERENCES `customer`(`customer_id`),
  `address_id` INTEGER REFERENCES `address`(`address_id`),
  `status_id` INTEGER,
  PRIMARY KEY (`customer_id`, `address_id`)
);

CREATE TABLE `order_status` (
  `status_id` INTEGER,
  `status_value` TEXT,
  PRIMARY KEY (`status_id`)
);

CREATE TABLE `publisher` (
  `publisher_id` INTEGER,
  `publisher_name` TEXT,
  PRIMARY KEY (`publisher_id`)
);

CREATE TABLE `book` (
  `book_id` INTEGER,
  `title` TEXT,
  `isbn13` TEXT,
  `language_id` INTEGER REFERENCES `book_language`(`language_id`),
  `num_pages` INTEGER,
  `publication_date` DATE,
  `publisher_id` INTEGER REFERENCES `publisher`(`publisher_id`),
  PRIMARY KEY (`book_id`)
);

CREATE TABLE `book_author` (
  `book_id` INTEGER REFERENCES `book`(`book_id`),
  `author_id` INTEGER REFERENCES `author`(`author_id`),
  PRIMARY KEY (`book_id`, `author_id`)
);

CREATE TABLE `shipping_method` (
  `method_id` INTEGER,
  `method_name` TEXT,
  `cost` REAL,
  PRIMARY KEY (`method_id`)
);

CREATE TABLE `cust_order` (
  `order_id` INTEGER,
  `order_date` DATETIME,
  `customer_id` INTEGER,
  `shipping_method_id` INTEGER,
  `dest_address_id` INTEGER,
  PRIMARY KEY (`order_id`)
);

CREATE TABLE `order_history` (
  `history_id` INTEGER,
  `order_id` INTEGER,
  `status_id` INTEGER,
  `status_date` DATETIME,
  PRIMARY KEY (`history_id`)
);

CREATE TABLE `order_line` (
  `line_id` INTEGER,
  `order_id` INTEGER,
  `book_id` INTEGER,
  `price` REAL,
  PRIMARY KEY (`line_id`)
);

Question:
What is the highest price at which a customer bought the book 'The Prophet'?

Evidence:
"The Prophet" is the title of the book; highest price refers to Max(price)

Database Schema:
CREATE TABLE `country` (
  `id` INTEGER,
  `country_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `ranking_system` (
  `id` INTEGER,
  `system_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `ranking_criteria` (
  `id` INTEGER,
  `ranking_system_id` INTEGER REFERENCES `ranking_system`(`id`),
  `criteria_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `university` (
  `id` INTEGER,
  `country_id` INTEGER REFERENCES `country`(`id`),
  `university_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `university_ranking_year` (
  `university_id` INTEGER REFERENCES `university`(`id`),
  `ranking_criteria_id` INTEGER REFERENCES `ranking_criteria`(`id`),
  `year` INTEGER,
  `score` INTEGER
);

CREATE TABLE `university_year` (
  `university_id` INTEGER REFERENCES `university`(`id`),
  `year` INTEGER,
  `num_students` INTEGER,
  `student_staff_ratio` REAL,
  `pct_international_students` INTEGER,
  `pct_female_students` INTEGER
);

Question:
For Chosun University, what was its score on "Influence Rank" in 2015?

Evidence:
Chosun University refers to university_name = 'Chosun University'; in 2015 refers to year = 2015; on "Influence Rank" refers to criteria_name = 'Influence Rank';

Database Schema:
CREATE TABLE `city` (
  `id` INTEGER,
  `city_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `games` (
  `id` INTEGER,
  `games_year` INTEGER,
  `games_name` TEXT,
  `season` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `games_city` (
  `games_id` INTEGER REFERENCES `games`(`id`),
  `city_id` INTEGER REFERENCES `city`(`id`)
);

CREATE TABLE `medal` (
  `id` INTEGER,
  `medal_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `noc_region` (
  `id` INTEGER,
  `noc` TEXT,
  `region_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `person` (
  `id` INTEGER,
  `full_name` TEXT,
  `gender` TEXT,
  `height` INTEGER,
  `weight` INTEGER,
  PRIMARY KEY (`id`)
);

CREATE TABLE `games_competitor` (
  `id` INTEGER,
  `games_id` INTEGER REFERENCES `games`(`id`),
  `person_id` INTEGER REFERENCES `person`(`id`),
  `age` INTEGER,
  PRIMARY KEY (`id`)
);

CREATE TABLE `person_region` (
  `person_id` INTEGER REFERENCES `person`(`id`),
  `region_id` INTEGER REFERENCES `noc_region`(`id`)
);

CREATE TABLE `sport` (
  `id` INTEGER,
  `sport_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `event` (
  `id` INTEGER,
  `sport_id` INTEGER REFERENCES `sport`(`id`),
  `event_name` TEXT,
  PRIMARY KEY (`id`)
);

CREATE TABLE `competitor_event` (
  `event_id` INTEGER REFERENCES `event`(`id`),
  `competitor_id` INTEGER REFERENCES `games_competitor`(`id`),
  `medal_id` INTEGER REFERENCES `medal`(`id`)
);

Question:
What is the percentage of the people who are under 35 and participated in the summer season?

Evidence:
DIVIDE(COUNT(age < 35) / COUNT(person_id)) as percentage where season = 'Summer';

Database Schema:
CREATE TABLE `ACCOUNTS` (
  `custid` NUMBER,
  `name` TEXT,
  PRIMARY KEY (`custid`)
);

CREATE TABLE `SAVINGS` (
  `custid` NUMBER REFERENCES `ACCOUNTS`(`custid`),
  `balance` NUMBER,
  PRIMARY KEY (`custid`)
);

CREATE TABLE `CHECKING` (
  `custid` NUMBER REFERENCES `ACCOUNTS`(`custid`),
  `balance` NUMBER,
  PRIMARY KEY (`custid`)
);

Question:
Find the name and total checking and savings balance of the accounts whose savings balance is lower than corresponding checking balance.

Database Schema:
CREATE TABLE `Songs` (
  `SongId` NUMBER,
  `Title` TEXT,
  PRIMARY KEY (`SongId`)
);

CREATE TABLE `Albums` (
  `AId` NUMBER,
  `Title` TEXT,
  `Year` NUMBER,
  `Label` TEXT,
  `Type` TEXT,
  PRIMARY KEY (`AId`)
);

CREATE TABLE `Band` (
  `Id` NUMBER,
  `Firstname` TEXT,
  `Lastname` TEXT,
  PRIMARY KEY (`Id`)
);

CREATE TABLE `Instruments` (
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  `BandmateId` NUMBER REFERENCES `Band`(`Id`),
  `Instrument` TEXT,
  PRIMARY KEY (`SongId`)
);

CREATE TABLE `Performance` (
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  `Bandmate` NUMBER REFERENCES `Band`(`Id`),
  `StagePosition` TEXT,
  PRIMARY KEY (`SongId`)
);

CREATE TABLE `Tracklists` (
  `AlbumId` NUMBER REFERENCES `Albums`(`AId`),
  `Position` NUMBER,
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  PRIMARY KEY (`AlbumId`)
);

CREATE TABLE `Vocals` (
  `SongId` NUMBER REFERENCES `Songs`(`SongId`),
  `Bandmate` NUMBER REFERENCES `Band`(`Id`),
  `Type` TEXT,
  PRIMARY KEY (`SongId`)
);

Question:
What types of vocals are used in the song "Badlands"?

Database Schema:
CREATE TABLE `Scientists` (
  `SSN` NUMBER,
  `Name` TEXT,
  PRIMARY KEY (`SSN`)
);

CREATE TABLE `Projects` (
  `Code` TEXT,
