What are the names of projects that have taken longer than the average number of hours for all projects?

Database Schema:
CREATE TABLE `bool` (
  `name` TEXT,
  PRIMARY KEY (`name`)
);

CREATE TABLE `person` (
  `name` TEXT,
  PRIMARY KEY (`name`)
);

CREATE TABLE `disabled` (
  `name` TEXT REFERENCES `person`(`name`),
  PRIMARY KEY (`name`)
);

CREATE TABLE `enlist` (
  `name` TEXT REFERENCES `person`(`name`),
  `organ` TEXT
);

CREATE TABLE `filed_for_bankrupcy` (
  `name` TEXT REFERENCES `person`(`name`),
  PRIMARY KEY (`name`)
);

CREATE TABLE `longest_absense_from_school` (
  `name` TEXT REFERENCES `person`(`name`),
  `month` INTEGER,
  PRIMARY KEY (`name`)
);

CREATE TABLE `male` (
  `name` TEXT REFERENCES `person`(`name`),
  PRIMARY KEY (`name`)
);

CREATE TABLE `no_payment_due` (
  `name` TEXT REFERENCES `person`(`name`),
  `bool` TEXT REFERENCES `bool`(`name`),
  PRIMARY KEY (`name`)
);

CREATE TABLE `unemployed` (
  `name` TEXT REFERENCES `person`(`name`),
  PRIMARY KEY (`name`)
);

CREATE TABLE `enrolled` (
  `name` TEXT REFERENCES `person`(`name`),
  `school` TEXT,
  `month` INTEGER,
  PRIMARY KEY (`name`, `school`)
);

Question:
Find the percentage of male students enlisted in the fire department.

Evidence:
percentage refers to DIVIDE(COUNT(organ = 'fire_department'), COUNT(name))

Database Schema:
CREATE TABLE `author` (
  `aid` NUMBER,
  `homepage` TEXT,
  `name` TEXT,
  `oid` NUMBER,
  PRIMARY KEY (`aid`)
);

CREATE TABLE `conference` (
  `cid` NUMBER,
  `homepage` TEXT,
  `name` TEXT,
  PRIMARY KEY (`cid`)
);

CREATE TABLE `domain` (
  `did` NUMBER,
  `name` TEXT,
  PRIMARY KEY (`did`)
);

CREATE TABLE `domain_author` (
  `aid` NUMBER REFERENCES `author`(`aid`),
  `did` NUMBER REFERENCES `domain`(`did`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `domain_conference` (
  `cid` NUMBER REFERENCES `conference`(`cid`),
  `did` NUMBER REFERENCES `domain`(`did`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `journal` (
  `homepage` TEXT,
  `jid` NUMBER,
  `name` TEXT,
  PRIMARY KEY (`jid`)
);

CREATE TABLE `domain_journal` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `jid` NUMBER REFERENCES `journal`(`jid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `keyword` (
  `keyword` TEXT,
  `kid` NUMBER,
  PRIMARY KEY (`kid`)
);

CREATE TABLE `domain_keyword` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `kid` NUMBER REFERENCES `keyword`(`kid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `publication` (
  `abstract` TEXT,
  `cid` TEXT REFERENCES `conference`(`cid`),
  `citation_num` NUMBER,
  `jid` NUMBER REFERENCES `journal`(`jid`),
  `pid` NUMBER,
  `reference_num` NUMBER,
  `title` TEXT,
  `year` NUMBER,
  PRIMARY KEY (`pid`)
);

CREATE TABLE `domain_publication` (
  `did` NUMBER REFERENCES `domain`(`did`),
  `pid` NUMBER REFERENCES `publication`(`pid`),
  PRIMARY KEY (`did`)
);

CREATE TABLE `organization` (
  `continent` TEXT,
  `homepage` TEXT,
  `name` TEXT,
  `oid` NUMBER,
  PRIMARY KEY (`oid`)
);

CREATE TABLE `publication_keyword` (
  `pid` NUMBER REFERENCES `publication`(`pid`),
  `kid` NUMBER REFERENCES `keyword`(`kid`),
  PRIMARY KEY (`kid`)
);

CREATE TABLE `writes` (
  `aid` NUMBER REFERENCES `author`(`aid`),
  `pid` NUMBER REFERENCES `publication`(`pid`),
  PRIMARY KEY (`aid`)
);

CREATE TABLE `cite` (
  `cited` NUMBER REFERENCES `publication`(`pid`),
  `citing` NUMBER REFERENCES `publication`(`pid`)
);

Question:
return me the authors who have papers in VLDB conference before 2002 .

